INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷112·太祖本纪三·广顺二年四月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a94812079efe6f0dad4431d10d0651494739b7f1/content/books/zizhi-tongjian/vol-290/year-0952/part-03/sources/library/jiuwudaishi-112-april-952/source.txt", "note": "《旧五代史》卷112·太祖本纪三·广顺二年四月，段落 jiu-wudaishi-205deb4a7860-p002672；已核上下文及传主，纸本及异文待核。", "id": "8029d1a3-0cc2-5301-a392-6c58079a1d2b"}, {"title": "旧五代史·卷112·太祖本纪三·广顺二年五月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a94812079efe6f0dad4431d10d0651494739b7f1/content/books/zizhi-tongjian/vol-290/year-0952/part-03/sources/library/jiuwudaishi-112-may-952/source.txt", "note": "《旧五代史》卷112·太祖本纪三·广顺二年五月，段落 jiu-wudaishi-205deb4a7860-p002673；已核上下文及传主，纸本及异文待核。", "id": "c2cdc014-a696-5c14-b431-c2a77dfa1bd7"}, {"title": "宋史·卷263·列传二十二·窦仪传·请赦兖州胁从", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a94812079efe6f0dad4431d10d0651494739b7f1/content/books/zizhi-tongjian/vol-290/year-0952/part-03/sources/library/songshi-263-dou-yi-clemency/source.txt", "note": "《宋史》卷263·列传二十二·窦仪传·请赦兖州胁从，段落 songshi-9c6e46fee832-p058265；已核上下文及传主，纸本及异文待核。", "id": "6f55505e-45f0-5881-92d6-f2f0841a15ed"}, {"title": "资治通鉴·卷290·广顺二年·四五月亲征兖州及相邻记事", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a94812079efe6f0dad4431d10d0651494739b7f1/content/books/zizhi-tongjian/vol-290/year-0952/part-03/sources/library/tongjian-290-952-april-may/source.txt", "note": "《资治通鉴》卷290·广顺二年·四五月亲征兖州及相邻记事，段落 zizhi-tongjian-a63549944a71-p003451；已核上下文及传主，纸本及异文待核。", "id": "ffdbdd7d-f017-517a-b258-cdea40188bd0"}, {"title": "新五代史·卷53·杂传四十一·慕容彦超传·城破与死亡", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a94812079efe6f0dad4431d10d0651494739b7f1/content/books/zizhi-tongjian/vol-290/year-0952/part-03/sources/library/xinwudaishi-053-murong-death/source.txt", "note": "《新五代史》卷53·杂传四十一·慕容彦超传·城破与死亡，段落 xin-wudaishi-b08f244b9241-p002084；已核上下文及传主，纸本及异文待核。", "id": "54dd4cdc-b231-58bb-a34c-210bc5d7847f"}, {"title": "资治通鉴·卷290·广顺二年·正月起及相邻追述", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/44575c9b45f3f29cba05ba49f0a7a9dc69fba5f3/content/books/zizhi-tongjian/vol-290/year-0952/part-01/sources/library/tongjian-290-952-january-continuation/source.txt", "note": "《资治通鉴》卷290·广顺二年·正月起及相邻追述，段落 zizhi-tongjian-a63549944a71-p003450；已核上下文及传主，纸本及异文待核。", "id": "937a0bab-01af-5f8d-90b3-d3d0aac5e04b"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "萧俨", "aliases": ["蕭儼"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐官员，943年开篇记为司门郎中、判大理寺。曾指责陈觉，又反对冯延巳兄弟所草允许卖子女的遗诏，说明李昪先前对此的处理。生卒年尚未核。", "biography": null, "status": "draft", "id": "e8d8e2fc-647f-5c18-8732-94948c94d59a"}, {"name": "冯延巳", "aliases": ["馮延巳", "冯延己", "馮延己", "冯延已"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐官员，曾任驾部郎中、齐王元帅府常书记。《资治通鉴》本段作冯延己及延已，《新五代史》作冯延巳；据同一南唐政局、陈觉及常梦锡等对应关系校核为同人，展示采用冯延巳，原文异体保留。生卒年尚未核。", "biography": null, "status": "draft", "id": "0b3ed4d7-1a4c-50a5-ad65-aee4b82089ba"}, {"name": "钟谟", "aliases": ["鍾謨"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "会稽人，南唐吏部郎中。949年条下与李德明一起参与国政，史书称两人以辩才聪慧受到李璟宠信。与后文同名外交官的进一步经历按年代续录，生卒年尚未录入。", "biography": null, "status": "draft", "id": "ee7c4ab6-a8d3-5f0a-8b05-ede060c3934c"}, {"name": "李德明", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐尚书员外郎。949年条下与钟谟一起参与国政，史书记两人受李璟宠信，但不是魏岑的同党。生卒年尚未录入。", "biography": null, "status": "draft", "id": "3aa99691-05a6-5807-a0c3-f56c9cebb4f1"}, {"name": "徐景运", "aliases": ["徐景運"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐前镇海节度使。952年任中书侍郎、同平章事，与冯延巳、孙晟同为宰相。未与徐景迁、徐景通混同，生卒年未载。", "biography": null, "status": "draft", "id": "69fac4e2-e7c9-5be1-9a5c-7df56a995594"}, {"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "李谷", "aliases": ["李穀"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：李谷，汝阴进士、送别友人。", "biography": null, "status": "draft", "id": "33cb8b51-1e37-5d5f-ab22-b339b991020d"}, {"name": "郑仁诲", "aliases": ["鄭仁誨"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "晋阳人，后周内客省使、恩州团练使。952年三月任枢密副使，新旧五代史同日记载。生卒年尚未录入。", "biography": null, "status": "draft", "id": "f7eb66ac-1c5c-5720-aa2e-9256e75c2b71"}, {"name": "郭崇", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周侍卫马军都指挥使。952年郭威亲征兖州时，充在京都巡检。生卒年尚未录入。", "biography": null, "status": "draft", "id": "da797339-8eeb-5a3d-aa29-97f251a5943c"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "李建期", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐将领。南唐取湖南以后，受李璟之命驻益阳、谋取朗州，较长时间没有取得成果。生卒年未载。", "biography": null, "status": "draft", "id": "a96853c0-b5fb-55c1-affb-4b16c6ccd874"}, {"name": "张峦", "aliases": ["張巒"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐黑云指挥使。951年十二月任知全州，防备南汉。《新五代史》保大十年另记他出兵争桂管失败，时序另保留。生卒年未载。", "biography": null, "status": "draft", "id": "660a73c2-c72e-5e9c-a384-6c53eff0c794"}, {"name": "孙晟", "aliases": ["孫晟", "孙凤", "孫鳳", "孙忌", "孫忌"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷276天成二年条所见人物：孙晟，判官、劝反者。", "biography": null, "status": "draft", "id": "38c30b43-89f4-5133-8970-38f2fb8f157e"}, {"name": "侯训", "aliases": ["侯訓"], "era": "五代十国", "birth_year": null, "death_year": 952, "description": "南唐统军使。952年奉李璟之命率五千兵从吉州路赴全州，与张峦合攻桂州，战败身死。生年未载。", "biography": null, "status": "draft", "id": "54925e78-2292-5369-a81e-98dc80f7c7b7"}, {"name": "慕容彦超", "aliases": ["慕容彥超"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋濮州刺史，原属吐谷浑，与刘知远同母。945年正月随皇甫遇侦察契丹军，在榆林店受围，与皇甫遇共同救回杜知敏，得到安审琦援军后返回相州。出生及死亡年本段未载。", "biography": null, "status": "draft", "id": "e0c11a24-a441-5d69-b8e3-b5bdc109357b"}, {"name": "慕容继勋", "aliases": ["慕容繼勳"], "era": "五代十国", "birth_year": null, "death_year": 952, "description": "慕容彦超之子。952年五月兖州城破后逃走，被追获杀死。《新五代史》另记率部五百人出奔被擒。生年未载。", "biography": null, "status": "draft", "id": "d3cdf2a2-9fd3-54bd-8907-43da5ce7dc12"}, {"name": "窦仪", "aliases": ["竇儀"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "蓟州人，后晋天平军观察判官。944年正月奉颜衎命向朝廷奏报周儒降契丹、引兵渡河及蔡行遇被俘，并向景延广说明与杨光远会合的危险。生卒年本批未核。", "biography": null, "status": "draft", "id": "9d318328-3904-5714-a390-ea527c3e9fd9"}, {"name": "冯道", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化元年条所见人物：冯道。", "biography": null, "status": "draft", "id": "16b195e8-f15a-5814-bdd2-934f10bbdf39"}, {"name": "范质", "aliases": ["范質", "範質"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "宗城人，后晋主客员外郎。944年六月戊辰任翰林学士。后续仕宦随编年主线补录。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "abe2c0af-4bf3-551b-83c9-f355ba085a0e"}, {"name": "颜衎", "aliases": ["顏衎"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋枢密直学士、工部郎中。939年废枢密院后，解除院内职务，保留本官。生卒年未载。", "biography": null, "status": "draft", "id": "b9f8cc2c-05c1-565a-a870-6fcd731c4ba9"}, {"name": "李建勋", "aliases": ["李建勳"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：李建勋，节度副使、屡陈功业者。", "biography": null, "status": "draft", "id": "6b23676b-32be-5201-8ad3-171b7cc648e3"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
